import Ajv from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

interface ValidationError {
  instancePath: string;
  dataPath?: string;
  keyword: string;
  message?: string;
  params: Record<string, unknown>;
}

type Validator = ((input: Record<string, unknown>) => boolean) & {errors?: ValidationError[] | null};

function validationMessage(error: ValidationError | undefined): string {
  const path = error?.instancePath || error?.dataPath || '/';
  const missingProperty = typeof error?.params.missingProperty === 'string' ? ` '${error.params.missingProperty}'` : '';
  const constraint = error?.keyword ? ` (${error.keyword})` : '';
  return `Input validation failed at ${path}${constraint}: ${error?.message ?? 'invalid input'}${missingProperty}`;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: Validator;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validator = new Ajv({
    allErrors: true,
    coerceTypes: false,
    strict: false,
    useDefaults: false,
    validateFormats: false,
  } as unknown as ConstructorParameters<typeof Ajv>[0]);
  private readonly compiledSchemas = new WeakMap<object, Validator>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileSchema(name: string, schema: Record<string, unknown>): Validator {
    const cached = this.compiledSchemas.get(schema);
    if (cached) return cached;

    try {
      const validator = this.validator.compile(schema) as Validator;
      this.compiledSchemas.set(schema, validator);
      return validator;
    } catch (error) {
      const reason = error instanceof Error ? error.message : 'invalid schema';
      throw new Error(`Failed to compile inputSchema for tool '${name}': ${reason}`, {cause: error});
    }
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validator =
      typeof definition === 'function' ? undefined : this.compileSchema(resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  // Validates input against the registered schema and returns rejection results; only unknown tools throw (specs/hal-engine-tool-input-validation/spec.md).
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = tool.validator ?? this.compileSchema(definition.name, definition.inputSchema);
    if (!validate(input)) {
      const errors = validate.errors ?? [];
      log.warn('tool', 'input validation failed', {
        name,
        failures: errors.map(error => ({
          path: error.instancePath || '/',
          keyword: error.keyword,
          message: error.message,
        })),
      });
      return {result: errors.map(validationMessage).join('; ')};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  it('returns a ToolResponse naming the missing required field and does not invoke the executor', async () => {
    let executorCalls = 0;
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'get weather',
        inputSchema: {type: 'object', required: ['location'], properties: {location: {type: 'string'}}},
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const toolResponse = await registry.execute('weather', {});

    expect({toolResult: toolResponse.result, executorCalls}).toEqual({
      toolResult: expect.stringMatching(/location.*required|required.*location/i),
      executorCalls: 0,
    });
  });

  it('compiles a static schema once at registration', async () => {
    const inputSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const registry = new ToolRegistry();
    registry.register(
      {name: 'weather', description: 'get weather', inputSchema},
      async input => `sunny in ${String(input.location)}`
    );

    const locationSchema = inputSchema.properties.location as {type: string};
    locationSchema.type = 'not-a-json-schema-type';

    await expect(registry.execute('weather', {location: 'Paris'})).resolves.toEqual({result: 'sunny in Paris'});
  });

  it('retains the schema compilation error as the registration error cause', () => {
    const registry = new ToolRegistry();

    try {
      registry.register(
        {
          name: 'broken',
          description: 'invalid schema',
          inputSchema: {type: 'object', properties: {location: {type: 'not-a-type'}}},
        },
        async () => 'unreachable'
      );
      throw new Error('expected registration to fail');
    } catch (error) {
      expect(error).toEqual(
        expect.objectContaining({
          message: expect.stringContaining("Failed to compile inputSchema for tool 'broken'"),
          cause: expect.any(Error),
        })
      );
    }
  });

  it('validates each call against the current function-valued schema', async () => {
    let useLocationSchema = true;
    const registry = new ToolRegistry();
    registry.register(
      () => ({
        name: 'weather',
        description: 'get weather',
        inputSchema: useLocationSchema
          ? {type: 'object', required: ['location'], properties: {location: {type: 'string'}}}
          : {type: 'object', required: ['units'], properties: {units: {type: 'string'}}},
      }),
      async input => `received ${Object.keys(input).join(',')}`
    );

    const firstResponse = await registry.execute('weather', {location: 'Paris'});
    useLocationSchema = false;
    const secondResponse = await registry.execute('weather', {location: 'Paris'});

    expect({firstResponse, secondResponse}).toEqual({
      firstResponse: {result: 'received location'},
      secondResponse: {result: expect.stringMatching(/units.*required|required.*units/i)},
    });
  });

  it('rejects an enum value with its field and constraint without exposing the value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'get weather',
        inputSchema: {type: 'object', properties: {units: {enum: ['celsius', 'fahrenheit']}}},
      },
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {units: 'kelvin'});

    expect({result: response.result, leaksValue: response.result.includes('kelvin')}).toEqual({
      result: expect.stringMatching(/units.*enum|enum.*units/i),
      leaksValue: false,
    });
  });

  it('passes valid input through unchanged, including undeclared properties, exactly once', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Paris', timezone: 'Europe/Paris'};
    const executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'weather',
        description: 'get weather',
        inputSchema: {type: 'object', required: ['location'], properties: {location: {type: 'string'}}},
      },
      async receivedInput => {
        executorInputs.push(receivedInput);
        return 'sunny';
      }
    );

    await expect(registry.execute('weather', input)).resolves.toEqual({result: 'sunny'});

    expect(executorInputs).toEqual([input]);
  });
});
